import java.sql.*;import java.nio.file.*;import com.visioncare.dao.DBContext;
public class DatabaseAudit {
 static String cell(String v){return v==null?"":v.replace("|","/").replace("\n"," ");}
 public static void main(String[]args)throws Exception{StringBuilder md=new StringBuilder("# Kiểm kê database phục vụ kiểm thử — 26/10/2026\n\n");try(Connection c=DBContext.getConnection();Statement s=c.createStatement()){
 md.append("Database ứng dụng: **").append(c.getCatalog()).append("**. Chỉ đọc database khác để lấy tên; không sửa/xóa/tạo database.\n\n## Database nhìn thấy trên SQL Server\n\n");try(ResultSet r=s.executeQuery("SELECT name FROM sys.databases WHERE HAS_DBACCESS(name)=1 ORDER BY name")){while(r.next())md.append("- ").append(r.getString(1)).append("\n");}
 md.append("\n## Toàn bộ bảng trong database ứng dụng\n\n| Bảng | Số dòng |\n|---|---:|\n");java.util.List<String[]>tables=new java.util.ArrayList<>();try(ResultSet r=s.executeQuery("SELECT SCHEMA_NAME(schema_id),name FROM sys.tables ORDER BY name")){while(r.next())tables.add(new String[]{r.getString(1),r.getString(2)});}
 for(String[]t:tables)try(ResultSet r=s.executeQuery("SELECT COUNT_BIG(*) FROM ["+t[0].replace("]","]]")+"].["+t[1].replace("]","]]")+"]")){r.next();md.append("| ").append(t[0]).append('.').append(t[1]).append(" | ").append(r.getLong(1)).append(" |\n");}
 String[][]checks={{"Lịch Confirmed thiếu hóa đơn","SELECT COUNT(*) FROM Appointment a WHERE a.Status='Confirmed' AND NOT EXISTS(SELECT 1 FROM Master_Invoice i WHERE i.Appointment_ID=a.Appointment_ID)"},{"Lịch có nhiều hóa đơn tổng","SELECT COUNT(*) FROM (SELECT Appointment_ID FROM Master_Invoice GROUP BY Appointment_ID HAVING COUNT(*)>1)x"},{"Hóa đơn đóng đủ tiền nhưng thiếu dấu chốt checkout (bao gồm phí khám)","SELECT COUNT(*) FROM Master_Invoice i WHERE i.Status='Paid' AND NOT EXISTS(SELECT 1 FROM Invoice_Checkout co WHERE co.Invoice_ID=i.Invoice_ID AND co.Finalized_At IS NOT NULL)"},{"Yêu cầu refund đang chờ nhưng không đủ điều kiện hủy trước checkin","SELECT COUNT(*) FROM Refund_Request rr JOIN Master_Invoice i ON i.Invoice_ID=rr.Invoice_ID JOIN Appointment a ON a.Appointment_ID=i.Appointment_ID WHERE rr.Status='Pending' AND NOT ("+com.visioncare.dao.RefundPolicy.ELIGIBLE+")"}};
 md.append("\n## Đối chiếu dữ liệu hiện có (trước seed)\n\n| Kiểm tra | Số dòng |\n|---|---:|\n");for(String[]q:checks)try(ResultSet r=s.executeQuery(q[1])){r.next();md.append("| ").append(q[0]).append(" | ").append(r.getLong(1)).append(" |\n");}
 md.append("\n## Cột và khóa ngoại\n\n");for(String[]t:tables){md.append("### ").append(t[1]).append("\n\n");try(PreparedStatement p=c.prepareStatement("SELECT COLUMN_NAME,DATA_TYPE,IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY ORDINAL_POSITION")){p.setString(1,t[0]);p.setString(2,t[1]);try(ResultSet r=p.executeQuery()){while(r.next())md.append("- `").append(r.getString(1)).append("` ").append(r.getString(2)).append(" (nullable=").append(r.getString(3)).append(")\n");}}}
 md.append("\n## Trạng thái và danh mục phục vụ seed\n\n");String[]qs={"SELECT Role_ID,Role_Name FROM Role","SELECT Status,COUNT(*) AS Rows FROM Appointment GROUP BY Status","SELECT TOP 12 Schedule_ID,Doctor_Employee_ID,Work_Date,Start_Time FROM Work_Schedule ws WHERE Work_Date>='2026-10-26' AND Status='Available' AND Doctor_Employee_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM Appointment a WHERE a.Schedule_ID=ws.Schedule_ID AND a.Status<>'Canceled') ORDER BY Work_Date,Start_Time,Schedule_ID","SELECT Supply_ID,Supply_Name,Price FROM Medical_Supply WHERE Price>0 ORDER BY Supply_ID"};for(String q:qs)try(ResultSet r=s.executeQuery(q)){while(r.next()){for(int i=1;i<=r.getMetaData().getColumnCount();i++)md.append(cell(r.getString(i))).append(" / ");md.append("\n\n");}}
 }Files.writeString(Path.of("docs/testing/database-audit-20261026.md"),md);System.out.println("Audit written to docs/testing/database-audit-20261026.md");}
}
